import * as THREE from './vendor/three/three.module.js';
// Photo-guided silhouette: side part, loose shoulder-length waves, blue blouse.
// The fitted head remains an approximation of the uploaded photographic references.
export function createMentorTeachingModel(model){
 model.updateMatrixWorld(true);model.traverse(mesh=>mesh.skeleton?.update());const head=model.getObjectByName('Head'),headPosition=head?.getWorldPosition(new THREE.Vector3())||new THREE.Vector3(0,1.55,0);
 model.traverse(mesh=>{if(!mesh.isMesh)return;if(/casualsuit|ponytail/i.test(mesh.name)){mesh.visible=false;return;}if(mesh.name==='Human'){const geometry=mesh.geometry.clone(),positions=geometry.attributes.position,indices=geometry.index?.array,kept=[],v=new THREE.Vector3();if(indices){const visible=i=>mesh.getVertexPosition(i,v).applyMatrix4(mesh.matrixWorld).y>headPosition.y-.075;for(let i=0;i<indices.length;i+=3)if(visible(indices[i])&&visible(indices[i+1])&&visible(indices[i+2]))kept.push(indices[i],indices[i+1],indices[i+2]);geometry.setIndex(kept);mesh.geometry.dispose();mesh.geometry=geometry;}}});
 const body=new THREE.Group(),blouse=new THREE.MeshStandardMaterial({color:'#2984b9',roughness:.72}),skirt=new THREE.MeshStandardMaterial({color:'#243040',roughness:.86}),skin=new THREE.MeshStandardMaterial({color:'#c79682',roughness:.82}),shoes=new THREE.MeshStandardMaterial({color:'#26313b',roughness:.45});
 const ellipsoid=(x,y,z,sx,sy,sz,material)=>{const mesh=new THREE.Mesh(new THREE.SphereGeometry(1,32,24),material);mesh.position.set(x,y,z);mesh.scale.set(sx,sy,sz);body.add(mesh);return mesh;};
 ellipsoid(0,.81,0,.185,.19,.12,blouse);ellipsoid(0,.66,0,.15,.09,.1,blouse);const neck=ellipsoid(0,1.0,0,.072,.1,.065,skin);
 const bottom=new THREE.Mesh(new THREE.CylinderGeometry(.15,.205,.3,40),skirt);bottom.position.set(0,.48,0);body.add(bottom);
 const arms=[];for(const sign of [-1,1]){const pivot=new THREE.Group();pivot.position.set(sign*.19,.89,0);body.add(pivot);const sleeve=new THREE.Mesh(new THREE.CapsuleGeometry(.055,.15,6,12),blouse);sleeve.position.y=-.095;pivot.add(sleeve);const elbow=new THREE.Group();elbow.position.y=-.2;pivot.add(elbow);const forearm=new THREE.Mesh(new THREE.CapsuleGeometry(.036,.12,6,12),skin);forearm.position.y=-.075;elbow.add(forearm);const hand=new THREE.Mesh(new THREE.SphereGeometry(1,16,12),skin);hand.position.set(0,-.165,.01);hand.scale.set(.042,.052,.029);elbow.add(hand);if(sign===1){const chalk=new THREE.Mesh(new THREE.CylinderGeometry(.005,.005,.045,8),new THREE.MeshStandardMaterial({color:'#f5efd7',roughness:1}));chalk.position.set(.02,-.17,.037);chalk.rotation.z=.4;elbow.add(chalk);}arms.push({pivot,elbow,hand,sign});ellipsoid(sign*.085,.2,0,.057,.155,.064,skin);ellipsoid(sign*.085,.045,.055,.07,.04,.115,shoes);}body.userData.arms=arms;
 const pearl=new THREE.MeshStandardMaterial({color:'#dfdcd3',metalness:.35,roughness:.3});for(let i=0;i<25;i++){const a=Math.PI*(.08+i*.035);ellipsoid(Math.cos(a)*.096,1.0-Math.sin(a)*.063,.116,.007,.007,.007,pearl);}
 const hair=new THREE.Group(),hairMaterial=new THREE.MeshStandardMaterial({color:'#242026',roughness:.78,metalness:.025}),highlight=new THREE.MeshStandardMaterial({color:'#302a2d',roughness:.62});
 const cap=new THREE.Mesh(new THREE.SphereGeometry(1,48,24,0,Math.PI*2,0,Math.PI*.48),hairMaterial);cap.position.set(0,.038,-.017);cap.scale.set(.106,.12,.103);hair.add(cap);
 // Thin, overlapping locks follow a common loose-wave silhouette, avoiding a ponytail.
 for(const sign of [-1,1])for(let lock=0;lock<34;lock++){
  const angle=lock/33*Math.PI*.95,x0=sign*(.075+.02*Math.sin(angle)),z0=-.04+.07*Math.cos(angle),length=.31+.11*Math.sin(angle*.75),points=[];
  for(let step=0;step<=9;step++){const t=step/9;points.push(new THREE.Vector3(x0+sign*(.017*t+.027*Math.sin(t*8+lock*.3)*t),.095-length*t,z0-.018*t+.035*Math.sin(t*9+lock*.15)*t));}
  hair.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),36,.0065+lock%3*.001,6,false),lock%8===0?highlight:hairMaterial));
 }
 for(let lock=0;lock<22;lock++){const x=(lock/21-.5)*.17,points=[];for(let step=0;step<=9;step++){const t=step/9;points.push(new THREE.Vector3(x+.012*Math.sin(t*8+lock)*t,.095-.51*t,-.08-.014*Math.cos(t*7+lock*.1)));}hair.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),32,.009,6,false),hairMaterial));}
 // A swept front section defines the side part without covering the eyes.
 for(let lock=0;lock<12;lock++){const points=[new THREE.Vector3(-.022,.15,-.01),new THREE.Vector3(.04,.136,.052),new THREE.Vector3(.087,.086,.052-lock*.003),new THREE.Vector3(.105,.012,.01-lock*.003)];hair.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points),24,.0045,5,false),hairMaterial));}
 const human=model.getObjectByName('Human'),headBounds=new THREE.Box3();if(human){human.skeleton?.update();const indices=human.geometry.index.array,v=new THREE.Vector3();for(const index of indices)headBounds.expandByPoint(human.getVertexPosition(index,v).applyMatrix4(human.matrixWorld));}
 if(human&&!headBounds.isEmpty()){const neckTop=headBounds.min.y+.045;neck.position.set(headPosition.x,(.91+neckTop)/2,headPosition.z);neck.scale.y=Math.max(.075,(neckTop-.91)/2+.035);}const hairOrigin=headPosition.clone();if(human){const size=headBounds.getSize(new THREE.Vector3());hairOrigin.y=headBounds.max.y-size.y*.44;hairOrigin.x=(headBounds.min.x+headBounds.max.x)/2;hairOrigin.z=(headBounds.min.z+headBounds.max.z)/2;hair.scale.set(Math.max(1,size.x/.19),Math.max(1,size.y/.24),Math.max(1,size.z/.2));}hair.position.copy(hairOrigin);body.add(hair);body.userData.hairOffset=hairOrigin.clone().sub(headPosition);body.userData.hair=hair;body.userData.headBone=head;body.userData.hairRest=head.getWorldQuaternion(new THREE.Quaternion());return body;
}
